from pathlib import Path
import sys,json,hashlib,re
W=Path(__file__).resolve().parent
sys.path.insert(0,'/Volumes/LaCie/open-commentary/_tools');from build_repo import load_commentary
c=load_commentary(str(W));ids=['art-'+str(n) for n in range(207,213)]+['art-212'+s for s in ['a','b','c','d','e','f','g','h','ha','hb','hc','hd','he','hf']]
(W/'sources/review-art-207-212hf-before-hashes.json').write_text(json.dumps({k:hashlib.sha256(v.encode()).hexdigest() for k,v in c.items()},indent=2)+'\n')
edits={}
edits['art-207']=c['art-207']+'''\n\n[Rechtbank Rotterdam 21 februari 2020](cases/RBROT-2020-1792-rehabilitatie.md), rov. 4.1, verklaarde een verzoek niet-ontvankelijk: uitvoering van een gehomologeerd akkoord en de overgelegde curatorverklaring bewezen in die zaak niet dat iedere erkende schuldeiser naar genoegen was voldaan. Volledige nominale betaling is volgens de rechtbank niet noodzakelijk, maar enkel akkoordbetaling volstaat evenmin. De stelling van de verzoeker onder 3.1 moet dus van het rechterlijke oordeel worden onderscheiden. Het betreft een concrete uitspraak in eerste aanleg, geen algemene eis dat uitsluitend één voorgeschreven modelverklaring bewijs kan leveren.'''
edits['art-208']=c['art-208']+'''\n\nEen historisch voorbeeld is [Rechtbank Almelo 15 december 1999](cases/RBALM-1999-AA3942-rehabilitatie.md). Daar vonden publicatie in de Staatscourant én een dagblad plaats. De huidige tekst noemt alleen de Staatscourant; uit dat oudere vonnis mag daarom geen actuele verplichte dagbladpublicatie worden afgeleid. De officiële historische toestand van 2002 bevestigt dat artikel 208 destijds ook aangewezen nieuwsbladen noemde.'''
edits['art-210']=c['art-210']+'''\n\nIn het [Almelose vonnis van 15 december 1999](cases/RBALM-1999-AA3942-rehabilitatie.md) waren sinds de publicatie meer dan twee maanden verstreken, was geen verzet ingekomen en concludeerde het Openbaar Ministerie tot toewijzing. De rechtbank stelde zelf vast dat aan de vereisten was voldaan en verleende rehabilitatie. Het vonnis illustreert dus geen automatische toewijzing wegens het uitblijven van bezwaren. De vroegere aanvullende dagbladpublicatie en de toenmalige verwijzing naar Rv zijn geen zonder meer actuele procesvereisten.'''
edits['art-212a']=c['art-212a']+'''\n\nBij onderdeel b onder 3 geldt een eigen minimum van twee deelnemers: exploitant, afwikkelende instantie, centrale tegenpartij, verrekeningsinstituut en indirecte deelnemer tellen daarbij niet mee. Dit mag niet worden verwisseld met de Nederlandse aanwijzingsroute van artikel 212d. De begripsbepalingen gelden uitdrukkelijk ook voor afdeling 11AA; de toepassingsomvang eindigt dus niet bij de artikelen over betalingssystemen.'''
edits['art-212b']=c['art-212b']+'''\n\nDe precieze rechtsgevolgen verschillen per lid. Lid 3 zegt dat de opgesomde regels niet aan derden kunnen worden tegengeworpen; het verklaart daarmee niet iedere handeling voor alle doeleinden onaantastbaar. Bij lid 2 gaat het zowel om de omschreven bevoegdheid als om de goederen waarop zij betrekking heeft. Lid 4 verklaart juist leden 1 en 3 overeenkomstig toepasselijk op toekenning en uitoefening van die bevoegdheid en op faillissement van een exploitant van een interoperabel systeem die geen deelnemer is. Voor lid 6 blijft een uitdrukkelijke bepaling in de systeemregels nodig voordat regels van een ander interoperabel systeem de eigen invoerings- en onherroepelijkheidstijden raken.'''
edits['art-212d']=c['art-212d']+'''\n\nLees de twee aanwijzingsroutes tekstueel afzonderlijk. Lid 1 noemt ook de systeemexploitant onder de niet mee te tellen rollen; lid 2 noemt die rol niet in zijn eigen uitsluitingslijst. Die lijsten mogen niet stilzwijgend gelijk worden gemaakt. Bovendien omvat lid 1 clearing óf uitvoering, terwijl lid 2 de uitvoering van opdrachten noemt. Lid 6 verwijst letterlijk naar een beschikking als bedoeld in lid 1; deze toelichting breidt die publicatieverwijzing niet zonder meer uit tot iedere andere beschikking. De informatieplicht van lid 8 rust op de instelling, geldt desgevraagd en vereist een gerechtvaardigd belang; dit is een andere informatieverhouding dan de melding door de exploitant aan DNB in lid 5.'''
edits['art-212g']=c['art-212g']+'''\n\nOnder j wordt een deposito slechts voor zover het voor vergoeding in aanmerking komt als gegarandeerd aangemerkt; onder m staat het vallen onder de werking van het stelsel centraal. Een rekening kan daarom niet uitsluitend met het etiket 'deposito' voor haar gehele saldo als gegarandeerd worden behandeld. Onder k is de deposito-overeenkomst de contractuele grondslag voor het houden van het deposito en onder h staat financiële instrumenten als afzonderlijke categorie. De opening van lid 1 betrekt afdeling 11AB uitdrukkelijk bij de definities; lid 2 beperkt zijn eigen vestigingsregel tekstueel tot deze afdeling. Die verschillende reikwijdte verdient bij een verwijzing buiten de bankafdeling aparte controle.'''
edits['art-212ha']=c['art-212ha'].replace('op het verstrijken van zeven dagen na de kennisgeving','op het verstrijken van zeven dagen na dagtekening van de kennisgeving')+'''\n\nLid 4 bevat alternatieven: de rechtbank kan na de bedoelde DNB-mededeling beslissen zonder tevens de volle zeven dagen af te wachten. Zonder die mededeling is het verstrijken van de termijn voldoende om deze specifieke wachtvoorwaarde te beëindigen; dat is geen automatische faillietverklaring. Lid 1 benoemt een oordeel van DNB of de Afwikkelingsraad naar bevoegdheid, maar legt het indienen van het verzoek bij DNB. De zeven dagen van lid 4 zijn evenmin de 'redelijke termijn' waarbinnen DNB op grond van lid 1 moet verzoeken.'''
edits['art-212hd']=c['art-212hd'].replace('waar een bijkantoor aanwezig is of grensoverschrijdend diensten worden verricht','waar een bijkantoor aanwezig is of waarnaar diensten worden verricht vanuit vestigingen in een andere lidstaat')+'''\n\nDe buitenlandse autoriteiten krijgen kennis van de inhoud van het verzoekschrift; de bank krijgt een afschrift. Dat zijn tekstueel verschillende verplichtingen. Bij grensoverschrijdende dienstverlening noemt de wet uitdrukkelijk de vestiging van waaruit de diensten worden verricht. Stel daarom niet zonder onderzoek ieder land waarin een klant woont gelijk aan een geadresseerde lidstaat. Deze aanvraagkennisgeving loopt naast de bijzondere melding bij eigen aangifte in artikel 212ha lid 3.'''
edits['art-212hf']=c['art-212hf']+'''\n\nHet voorwerp van het verweer is afgebakend tot DNB's oordeel over onderdelen a en b van artikel 18 lid 1 van de genoemde verordening. Onderdeel c, waarnaar artikel 212ha lid 1 verwijst voor het algemeen belang, wordt hier niet genoemd. De tekst geeft dus geen grond om deze redelijkheidstoets zonder meer tot elk oordeel van iedere Europese autoriteit of tot ieder besluit in het afwikkelingstraject uit te breiden. Het vooraf bieden van gelegenheid om gehoord te worden en de inhoudelijke beoordeling van een daadwerkelijk gevoerd verweer blijven afzonderlijke stappen.'''
for p in (W/'commentary').glob('*.md'):
 s=p.read_text()
 for k,v in edits.items():
  pattern=r'(^=== '+re.escape(k)+r'\n)(.*?)(?=^=== |\Z)'
  s=re.sub(pattern,lambda m:m[1]+v.rstrip()+'\n\n',s,flags=re.M|re.S)
 p.write_text(s) if s!=p.read_text() else None
print('changed',len(edits))
